import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${select({ id: "dtElement", label: "Element type", options: [{label:"Dialog modal",value:"dialog"},{label:"Popover",value:"popover"},{label:"Details disclosure",value:"details"},{label:"Custom (display toggle)",value:"custom"}], value: "dialog"})}${select({ id: "dtEffect", label: "Animation effect", options: [{label:"Fade in/out",value:"fade"},{label:"Slide down/up",value:"slide-down"},{label:"Scale + fade",value:"scale-fade"},{label:"Slide from right",value:"slide-right"}], value: "fade"})}${field({ id: "dtSelector", label: "Element selector", value: ".my-dialog" })}${field({ id: "dtDuration", label: "Duration ms", value: "300", type: "number" })}</div>`,generate(root) {const element = root.querySelector("#dtElement").value;const effect = root.querySelector("#dtEffect").value;let selector = root.querySelector("#dtSelector").value.trim() || ".my-dialog";const duration = root.querySelector("#dtDuration").value || "300";let transitionCSS, startingCSS, displayCSS, triggerNote;if (effect === "fade") {transitionCSS = `transition: opacity ${duration}ms;`;startingCSS = ` opacity: 0;`;displayCSS = ` opacity: 1;`;} else if (effect === "slide-down") {transitionCSS = `transition: opacity ${duration}ms, transform ${duration}ms;`;startingCSS = ` opacity: 0;\n transform: translateY(-20px);`;displayCSS = ` opacity: 1;\n transform: translateY(0);`;} else if (effect === "scale-fade") {transitionCSS = `transition: opacity ${duration}ms, transform ${duration}ms, display ${duration}ms allow-discrete, overlay ${duration}ms allow-discrete;`;startingCSS = ` opacity: 0;\n transform: scale(0.9);`;displayCSS = ` opacity: 1;\n transform: scale(1);`;} else {transitionCSS = `transition: opacity ${duration}ms, transform ${duration}ms;`;startingCSS = ` opacity: 0;\n transform: translateX(30px);`;displayCSS = ` opacity: 1;\n transform: translateX(0);`;}if (element === "dialog") {triggerNote = "Trigger: element.showModal() to open, element.close() to close.";} else if (element === "popover") {triggerNote = "Trigger: popover attribute or element.showPopover() / hidePopover().";} else if (element === "details") {selector = `${selector}[open]`;triggerNote = "Trigger: toggle open attribute on the <details> element.";} else {triggerNote = "Trigger: toggle display between none and block.";}const output = `/* Discrete Transition for ${element.charAt(0).toUpperCase() + element.slice(1)} *//* Browser support: Chrome 117+, Edge 117+, Safari 18+ */@starting-style {${selector} {${startingCSS}}}${selector} {${displayCSS}${transitionCSS}transition-behavior: allow-discrete;}/* ${triggerNote}transition-behavior: allow-discrete enables transitioning on display and overlay.@starting-style defines the initial appearance state. */`;return { output };}};